import sys

def is_hill_number(n):
    s = str(n)
    i = 0
    while i < len(s) - 1 and s[i] <= s[i + 1]:
        i += 1
    while i < len(s) - 1 and s[i] >= s[i + 1]:
        i += 1
    return i == len(s) - 1

def count_hill_numbers(limit):
    dp = [[[0 for _ in range(2)] for _ in range(10)] for _ in range(20)]
    dp[0][0][0] = 1
    result = 0

    def dfs(pos, last_digit, is_limit, is_increasing):
        nonlocal result
        if pos == 0:
            result += 1
            return
        up_limit = int(limit[pos - 1]) if is_limit else 9
        for digit in range(up_limit + 1):
            if is_increasing and digit < last_digit:
                continue
            new_is_limit = is_limit and (digit == up_limit)
            if digit == last_digit:
                dfs(pos - 1, digit, new_is_limit, is_increasing)
            else:
                dfs(pos - 1, digit, new_is_limit, False)

    limit_str = str(limit)
    length = len(limit_str)
    for i in range(1, length):
        for d in range(1, 10):
            dfs(i - 1, d, False, True)
    for d in range(1, int(limit_str[0])):
        dfs(length - 1, d, False, True)
    if is_hill_number(limit):
        result -= 1
        result += 1
    return result

def main():
    n = int(sys.stdin.read().strip())
    if is_hill_number(n):
        print(count_hill_numbers(n))
    else:
        print(-1)

main()
